import logging
import os.path
import re
from collections import OrderedDict

import yaml

from taf.ul.bts_kpi_report_generator.Exception import KPINoFileRelease, KPIFailFormatData


class ReadSourceKPI(object):
    def __init__(self, source_kpi_raw, kpi_to_generate_raw, kpi_type_raw):
        """
        :param source_kpi_raw: parameters can be name release with catalog sources_files or path to YAML file or dict
        :param kpi_to_generate_raw: parameters can be path to YAML file or dict or str 'all'
                example list after convert YAML -> dict Python: {LTE_5000a: 10, LTE_5000b: 11},
                format YAML: LTE_5000a: 10
                             LTE_5000b: 11
        """
        self.__source_kpi_raw = source_kpi_raw
        self.__kpi_to_generate_raw = kpi_to_generate_raw
        self.type_kpi = kpi_type_raw
        self.__source_kpi = None
        self.__kpi_to_generate = None
        self.__use_kpi = OrderedDict()
        self.__release_version = 'NA'
        self.__counters_need = set()
        self.__counters_name = {}
        self.__categories = {}
        self.__warnings = []

    @property
    def type_kpi(self):
        return self.__kpi_type

    @type_kpi.setter
    def type_kpi(self, version_report_raw):
        if version_report_raw is None and not isinstance(self.__source_kpi_raw, dict):
            source_kpi_name = os.path.basename(self.__source_kpi_raw)
            if 'LTE' in source_kpi_name:
                self.__kpi_type = 'LTE'
            elif '5G' in source_kpi_name:
                self.__kpi_type = '5G'
        elif version_report_raw in ['LTE', '5G']:
            self.__kpi_type = version_report_raw
        else:
            raise Exception('Not supported KPI type')

    @property
    def release_version(self):
        """
        Getter, return name release or path to file with release or NA, if release is with dict
        :return: string, example: 'LTE19A' or /home/.. or 'NA'
        """
        return self.__release_version

    @property
    def use_kpi(self):
        """
        Getter, read release file is dict
        :return: dict with YAML
        """
        return self.__use_kpi

    @property
    def counters_need(self):
        """
        Getter, return counter need result chose KPI (use counter in formula)
        :return: set with name counter, example: {M01, M02, ..}
        """
        return self.__counters_need

    @property
    def counters_name(self):
        """
        Getter, return counters name with release (DEPENDENCIES)
        :return: dict with counter and name, example: {'M8007C0': 'Number of Data Radio Bearers attempted to setup', ...}
        """
        return self.__counters_name

    @property
    def categories(self):
        """
        Getter, return categories read with YAML
        :return: dict with list use KPI, example: {'Accessibility': ['LTE_5003a'], 'Retainability': ['LTE_5004a', 'LTE_5004b']}
        """
        return self.__categories

    @property
    def warnings(self):
        """
        Getter, return warning with release
        :return: list with warnings, example: ['LTE_5000a: KPI is not in putting release', 'LTE_5000b: KPI is not in putting release']
        """
        return self.__warnings

    def parse_kpi(self):
        """
        Method create all parameters access thought getter: release version, use_kpi, counters_need, counters_name, categories, warnings
        """
        self.__set_source_kpi()
        self.__set_kpi_to_generate()
        self.__get_needed_kpis()
        self.__get_required_counters_and_assign_kpis_to_categories()

    def __set_source_kpi(self):
        if isinstance(self.__source_kpi_raw, dict):
            self.__source_kpi = self.__source_kpi_raw
        elif os.path.isfile(self.__source_kpi_raw):
            self.__source_kpi = self.__open_file_yaml(self.__source_kpi_raw)
        else:
            path_source_files, files = self.__get_path_source_files()
            if self.__source_kpi_raw in [file for file in files]:
                self.__source_kpi = self.__open_file_yaml(os.path.join(path_source_files, self.__source_kpi_raw))
            else:
                raise KPINoFileRelease

    def __set_kpi_to_generate(self):
        if isinstance(self.__kpi_to_generate_raw, dict) or self.__kpi_to_generate_raw == 'all':
            self.__kpi_to_generate = self.__kpi_to_generate_raw
        elif os.path.isfile(self.__kpi_to_generate_raw):
            self.__kpi_to_generate = self.__open_file_yaml(self.__kpi_to_generate_raw)
        else:
            raise KPIFailFormatData

    @staticmethod
    def __get_path_source_files():
        path_file = os.path.abspath(__file__)
        path_bts_kpi_report = os.path.dirname(os.path.dirname(path_file))
        path_source_files = os.path.join(path_bts_kpi_report, 'source_files')
        files = os.listdir(path_source_files)
        return path_source_files, files

    @staticmethod
    def __open_file_yaml(path_file):
        with open(path_file, 'r') as stream:
            try:
                return yaml.safe_load(stream)
            except yaml.YAMLError as exc:
                logging.critical(exc)

    def __get_needed_kpis(self):
        if 'all' == self.__kpi_to_generate:
            for kpi in self.__source_kpi:
                self.use_kpi[kpi] = self.__source_kpi[kpi]
                self.use_kpi[kpi]['TARGET'] = 'NA'
        else:
            self.__search_version_kpi()

    def __search_version_kpi(self):
        version_search = {'LTE': r'LTE_[0-9]+$', '5G': r'NR_[0-9]+$'}
        for kpi in sorted(self.__kpi_to_generate):
            if kpi in self.__source_kpi:
                self.use_kpi[kpi] = self.__source_kpi[kpi]
                self.use_kpi[kpi]['TARGET'] = self.__kpi_to_generate[kpi]
            elif re.search(version_search[self.__kpi_type], kpi):
                list_version = self.__get_all_version_of_kpi(kpi)
                if len(list_version) == 0:
                    warning = '{}: KPI is not in source formulas'.format(kpi)
                    logging.warning(warning)
                    self.__warnings.append(warning)
                else:
                    kpi_new = sorted(list_version)[-1]
                    self.use_kpi[kpi_new] = self.__source_kpi[kpi_new]
                    self.use_kpi[kpi_new]['TARGET'] = self.__kpi_to_generate[kpi]
            else:
                warning = '{}: KPI have not version in source formulas'. format(kpi)
                logging.warning(warning)
                self.__warnings.append(warning)

    def __get_all_version_of_kpi(self, kpi):
        list_version = []
        for version_kpi in self.__source_kpi:
            if kpi in version_kpi:
                list_version.append(version_kpi)
        return list_version

    def __get_required_counters_and_assign_kpis_to_categories(self):
        for kpi in self.__use_kpi:
            if 'DEPENDENCIES' in self.__use_kpi[kpi]:
                for dependency in self.__use_kpi[kpi]['DEPENDENCIES']:
                    self.__counters_need.add(dependency)
                    self.__counters_name[dependency] = self.__use_kpi[kpi]['DEPENDENCIES'][dependency]
            if 'CATEGORY' in self.__use_kpi[kpi]:
                self.__get_kpi_categories(kpi)

    def __get_kpi_categories(self, kpi):
        if isinstance(self.__use_kpi[kpi]['CATEGORY'], list):
            self.__get_list_category(kpi)

        elif isinstance(self.__use_kpi[kpi]['CATEGORY'], str):
            category = self.__use_kpi[kpi]['CATEGORY']
            if category in None:
                category = 'Others'
            if category not in self.__categories:
                self.__categories[category] = []
            self.__categories[category] = kpi

    def __get_list_category(self, kpi):
        for category in self.__use_kpi[kpi]['CATEGORY']:
            if category is None:
                category = 'Others'
            if category not in self.__categories:
                self.__categories[category] = []
            self.__categories[category].append(kpi)
